/* error and recovery */
.erc-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.erc-head .t{font-weight:600;font-size:14px}
#erc-list{padding:6px 0}
.erc-row{display:flex;align-items:flex-start;gap:12px;padding:8px 16px;font-size:13px;color:var(--text);transition:color .3s}
.erc-row.wait{color:var(--text-dim)}
.erc-row .st{width:16px;height:20px;flex:none;display:grid;place-items:center}
.erc-row .note{display:block;margin-top:2px;font-size:12px;color:var(--muted)}
.erc-row.fail .note{color:var(--danger)}
.erc-row.skip span:not(.st):not(.note){color:var(--muted);text-decoration:line-through}
.erc-box{display:grid;grid-template-rows:1fr;transition:grid-template-rows .4s var(--ease)}
.erc-box>div{overflow:hidden}
.erc-box.shut{grid-template-rows:0fr}
.erc-in{padding:12px 16px 16px;border-top:1px solid var(--line)}
.erc-q{font-size:13px;font-weight:600;margin-bottom:8px}
.erc-opts{display:flex;flex-direction:column;gap:4px;margin-bottom:12px}
.erc-opt{display:flex;align-items:center;gap:10px;padding:8px 10px;font-size:13px;text-align:left;color:var(--text-dim);transition:background .2s,color .2s}
.erc-opt:hover{background:var(--chip);color:var(--text)}
.erc-opt.on{background:var(--chip);color:var(--text)}
.erc-opt i{width:14px;height:14px;flex:none;border:1px solid var(--muted);border-radius:50%;transition:border-color .2s,box-shadow .2s}
.erc-opt.on i{border-color:var(--accent);box-shadow:inset 0 0 0 3px var(--panel),inset 0 0 0 7px var(--accent)}
#erc-go{padding:8px 12px;font-size:13px}

/* ---------- error and recovery ---------- */
{
  const list = $('#erc-list'), sum = $('#erc-sum'), box = $('#erc-box'), go = $('#erc-go'), opts = $$('#erc-opts .erc-opt');
  const steps = [['Pull 1,240 deals from the CRM','Done in 8s'],['Write to the Pipeline 2026 sheet',''],['Post the summary in #sales','']];
  let ts = [], pick = 'retry';
  const row = i => list.children[i];
  function set(i, state, note){
    const r = row(i); r.className = 'erc-row ' + state;
    const icn = { done:ic('check_circle','sm icon-in s-done'), fail:ic('error','sm icon-in s-fail'), run:'<i class="spin"></i>', wait:ic('schedule','sm s-wait'), skip:ic('chevron_right','sm s-wait'), hand:ic('person','sm icon-in s-run') }[state];
    r.querySelector('.st').innerHTML = icn;
    r.querySelector('.note').textContent = note || '';
  }
  function reset(){
    ts.forEach(clearTimeout); ts = [];
    list.innerHTML = steps.map(s => `<div class="erc-row"><span class="st"></span><span>${s[0]}<span class="note"></span></span></div>`).join('');
    set(0, 'done', steps[0][1]); set(1, 'fail', '403, the agent lost edit access to this sheet'); set(2, 'wait');
    box.classList.remove('shut'); go.disabled = false; choose('retry', true);
    swapText(sum, 'Stopped at step 2');
  }
  function choose(o, quiet){
    pick = o; opts.forEach(b => { const on = b.dataset.o === o; b.classList.toggle('on', on); b.setAttribute('aria-checked', on); });
    if (!quiet) Sound.play('tab');
  }
  opts.forEach(b => b.addEventListener('click', () => choose(b.dataset.o)));
  const later = (ms, fn) => ts.push(setTimeout(fn, ms));
  function last(){
    set(2, 'run'); later(900, () => { set(2, 'done', 'Posted to 14 people'); Sound.play('done'); ambient('c109', 'tick'); });
  }
  go.addEventListener('click', () => {
    go.disabled = true; box.classList.add('shut'); Sound.play('tab');
    if (pick === 'retry'){
      set(1, 'run', 'Waiting for edit access'); swapText(sum, 'Recovering');
      later(1100, () => { set(1, 'run', 'Access granted, retrying'); });
      later(2000, () => { set(1, 'done', 'Wrote 1,240 rows'); last(); });
      later(2950, () => swapText(sum, 'Recovered, all steps done'));
    } else if (pick === 'skip'){
      set(1, 'skip', 'Skipped, nothing was written'); swapText(sum, 'Continuing without step 2');
      later(400, last); later(1350, () => swapText(sum, '2 of 3 steps done'));
    } else {
      set(1, 'hand', 'Maya has the error, the logs and the last good state'); swapText(sum, 'Waiting on Maya'); Sound.play('pop');
    }
  });
  $('#erc-play').addEventListener('click', () => { Sound.play('tab'); reset(); });
  reset();
  whenSeen($('#c109'), () => ambient('c109', 'fail'));
}
